(146,1,'district','give me report ward wise','SELECT w.name,\n       COUNT(DISTINCT g.ward_id)\nFROM grievances g\nJOIN pregnant_women pw ON g.pregnant_woman_id = pw.id\nJOIN blocks b ON pw.block_id = b.id\nJOIN wards w ON b.code = w.code\nWHERE pw.district_id = 1 GROUP BY w.name',12398,0,1,NULL,'ollama','2026-03-03 07:04:40','[]',NULL,'completed'),
(147,1,'district','hi ','SELECT COUNT(*)\nFROM pregnant_women pw\nJOIN usg_appointments ua ON pw.id = ua.pregnant_woman_id\nWHERE pw.district_id = 1 AND MONTH(ua.scheduled_date) = MONTH(CURDATE())',14922,1,1,NULL,'ollama','2026-03-03 07:05:11','[{\"COUNT(*)\": 1}]','{\"type\": \"metric\", \"config\": {\"title\": \"hi \", \"value\": 1, \"label\": \"Count(*)\"}}','completed'),
(148,1,'district','pls give me report of astarang block report','SELECT b.name,\n       COUNT(pw.id)\nFROM pregnant_women pw\nJOIN blocks b ON pw.block_id = b.id\nWHERE pw.district_id = 1 AND b.code = \'ASTARANG\'\nGROUP BY b.name',8983,0,1,NULL,'ollama','2026-03-03 07:05:41','[]',NULL,'completed'),
