(179,1,'district','Appointments trend by month','SELECT MONTH(ua.scheduled_date) AS scheduled_month,\n       YEAR(ua.scheduled_date) AS scheduled_year,\n       COUNT(*) AS total_appointments\nFROM usg_appointments ua\nJOIN pregnant_women pw ON ua.pregnant_woman_id = pw.id\nWHERE pw.district_id = 1 GROUP BY MONTH(ua.scheduled_date),\n         YEAR(ua.scheduled_date)\nORDER BY scheduled_year,\n         scheduled_month',18844,2,1,NULL,'ollama','2026-03-24 17:54:27','[{\"scheduled_month\": 2, \"scheduled_year\": 2026, \"total_appointments\": 27}, {\"scheduled_month\": 3, \"scheduled_year\": 2026, \"total_appointments\": 14}]','{\"type\": \"table\", \"config\": {\"title\": \"Appointments trend by month\", \"columns\": [{\"field\": \"scheduled_month\", \"label\": \"Scheduled Month\"}, {\"field\": \"scheduled_year\", \"label\": \"Scheduled Year\"}, {\"field\": \"total_appointments\", \"label\": \"Total Appointments\"}], \"data\": [{\"scheduled_month\": 2, \"scheduled_year\": 2026, \"total_appointments\": 27}, {\"scheduled_month\": 3, \"scheduled_year\": 2026, \"total_appointments\": 14}]}}','completed'),
(180,1,'district','High risk cases distribution','SELECT pw.district_id,\n       COUNT(pw.id) AS high_risk_count\nFROM pregnant_women pw\nJOIN usg_appointments ua ON pw.id = ua.pregnant_woman_id\nWHERE pw.district_id = 1 AND ua.is_high_risk = 1\nGROUP BY pw.district_id',77721,1,1,NULL,'ollama','2026-03-25 06:39:19','[{\"district_id\": 1, \"high_risk_count\": 1}]','{\"type\": \"table\", \"config\": {\"title\": \"High risk cases distribution\", \"columns\": [{\"field\": \"district_id\", \"label\": \"District Id\"}, {\"field\": \"high_risk_count\", \"label\": \"High Risk Count\"}], \"data\": [{\"district_id\": 1, \"high_risk_count\": 1}]}}','completed'),
